import{z as p,x as A,o as E,c as B,q as i,j as s,D as e,d as r,s as n,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"心跳与超时","description":"","frontmatter":{"title":"心跳与超时","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heartbeat-timeout.md","filePath":"cs/heartbeat-timeout.md","lastUpdated":1791413859000}'),d={name:"cs/heartbeat-timeout.md"};function T(m,a,h,c,f,u){const l=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="心跳与超时" tabindex="-1">心跳与超时 <a class="header-anchor" href="#心跳与超时" aria-label="Permalink to &quot;心跳与超时&quot;">​</a></h1><div class="epigraph"><p>空闲连接与半开要用主动心跳在应用层刷新；超时值要大于 RTT 与短暂拥塞，小于用户可忍受的失败检测。</p><footer>—— 据 RFC 1122 对照；gRPC keepalive；WebSocket ping 整理</footer></div><p><a href="/cs/keepalive-half-open">TCP keepalive</a> 太慢。<a href="/cs/message-framing">成帧</a> 已能发小消息。<a href="/cs/message-framing">上一课</a> 留下存活检测。缺口是<strong>应用心跳</strong>：间隔、超时、与 RTO 叠。本课不把重试写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反向代理、NAT、Maglev 都可能静默丢空闲。应用 ping/pong：间隔 15–60 s 常见，远短于 TCP keepalive。超时：连续未应答则拆，触发发现换后端。与 NTP 无关。无线调度抖动要给余量，否则假死。SSE 用注释行当心跳。QUIC PING 帧。过频心跳在万连接上成 C10K 负载。</p><p>不要把心跳当业务数据。</p><p><span class="marginnote">直觉类比：半开连接像「对方早挂了电话，你这边通话图标还亮着」——中间设备悄悄掐线，两端都不知情。心跳就是每半分钟互相喊一声「还在吗」，喊了没应答再挂断，才知道通话真的断了。</span></p><p><span class="marginnote">间隔无唯一 RFC。本课钉原则。</span></p><h3 id="值在-rtt-与-nat-之间" tabindex="-1">值在 RTT 与 NAT 之间 <a class="header-anchor" href="#值在-rtt-与-nat-之间" aria-label="Permalink to &quot;值在 RTT 与 NAT 之间&quot;">​</a></h3><p>太短杀卫星会话，太长留半开。心跳也是 C10K 负载。三层心跳要错开防同步。不是业务数据。</p><p><span class="marginnote">数字实例：跨洋 RTT 约 150 毫秒，卫星链路 600 毫秒还常抖到 1 秒；家用 NAT 的 UDP 表项常 30–60 秒无流量就删。于是「间隔 15–30 秒、连续 2 次未应答才判死」是从这些数字之间夹出来的常见取法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：传输 keepalive / 应用心跳 / LB 健康检查。画：定时发 → 等 pong → 失败则关。与 ICE 刷新一致。</p>',13)),(E(),s(o,null,{default:e(()=>[n(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TMR%5B%22%E5%AE%9A%E6%97%B6%22%5D%20--%3E%20PING%5B%22%E5%BF%83%E8%B7%B3%E5%B8%A7%22%5D%0A%20%20PING%20--%3E%20PONG%5B%22%E5%BA%94%E7%AD%94%22%5D%0A%20%20FAIL%5B%22%E8%B6%85%E6%97%B6%22%5D%20--%3E%20CLOSE%5B%22%E6%8B%86%E8%BF%9E%E6%8E%A5%E5%B9%B6%E5%8F%91%E7%8E%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"超时 \\(\\lt\\) 2×RTT 会在卫星上误杀。超时 >> NAT 会话则半开。与 ABR 无关。服务发现心跳是控制面，连接心跳是数据面会话。",-1)),a[5]||(a[5]=t("p",null,"超时值的下界与上界各由谁决定：",-1)),(E(),s(o,null,{default:e(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%80%89%E8%B6%85%E6%97%B6%E5%80%BC%20T%22%5D%20--%3E%20LO%5B%22%E4%B8%8B%E7%95%8C%3A%20%E7%9B%96%E4%BD%8F%20RTT%2B%E6%8A%96%E5%8A%A8%E4%BD%99%E9%87%8F%22%5D%0A%20%20LO%20--%3E%20E1%5B%22%E4%BD%8E%E4%BA%8E%E5%AE%83%3A%20%E6%85%A2%E9%93%BE%E8%B7%AF%E8%A2%AB%E8%AF%AF%E6%9D%80%22%5D%0A%20%20T%20--%3E%20HI%5B%22%E4%B8%8A%E7%95%8C%3A%20%E5%8E%8B%E4%BD%8F%20NAT%20%E7%A9%BA%E9%97%B2%E4%B8%8E%E7%94%A8%E6%88%B7%E8%80%90%E5%BF%83%22%5D%0A%20%20HI%20--%3E%20E2%5B%22%E9%AB%98%E4%BA%8E%E5%AE%83%3A%20%E5%8D%8A%E5%BC%80%E5%A0%86%E7%A7%AF%2C%20%E6%95%85%E9%9A%9C%E5%8F%91%E7%8E%B0%E6%85%A2%22%5D%0A%20%20LO%20--%3E%20WIN%5B%22T%20%E8%90%BD%E5%9C%A8%E7%AA%97%E5%8F%A3%E5%86%85%22%5D%0A%20%20HI%20--%3E%20WIN%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：初学者以为心跳「只是保活，没有安全面」。无认证的心跳等于送分——攻击者开一万条连接只回 pong 不做业务，就把你的连接表与心跳算力占满。心跳帧要与会话认证绑定，陌生人答了也不算数。</span></p><p>安全：无认证的心跳可被用来保活攻击连接表，要绑会话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入指数退避的全部（下一课重试）。重试与幂等是下一课。后课默认：应用心跳检测会话死活；值按 RTT 与 NAT 定。</p><p>三层心跳（TCP、HTTP、业务）要错开，避免同步风暴。</p><p>下一课<a href="/cs/retry-idempotency">重试与幂等</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应用心跳补 NAT 与代理空闲策略。</li><li>超时在 RTT 与用户等待之间。</li><li>规模上心跳也是负载。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1122 对照；应用实践。</li></ul>',8))])}const P=p(d,[["render",T]]);export{C as __pageData,P as default};
